module spike_cave (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] N,\n    input [3:0] M,\n    input [15:0][39:0] edges,  // M_MAX=16 elements\n    output reg [31:0] danger [0:7],  // N_MAX=8\n    output reg done\n);\n\nparameter N_MAX = 8;\nparameter M_MAX = 16;\nparameter MOD = 32'd1000000007;\nparameter [63:0] INF = 64'hFFFFFFFF_FFFFFFFF;\n\n// State encoding\nlocalparam [2:0] IDLE       = 3'd0;\nlocalparam [2:0] INIT       = 3'd1;\nlocalparam [2:0] LOAD_EDGES = 3'd2;\nlocalparam [2:0] FLOYD      = 3'd3;\nlocalparam [2:0] SUM        = 3'd4;\nlocalparam [2:0] DONE_STATE = 3'd5;\n\nreg [2:0] state, next_state;\n\n// Captured N and M\nreg [2:0] n_reg;\nreg [3:0] m_reg;\n\n// Dist matrix\nreg [63:0] dist [0:7][0:7];  // N_MAX x N_MAX\n\n// Counters\nreg [2:0] init_i, init_j;\nreg [3:0] edge_idx;\nreg [2:0] k_cnt, i_cnt, j_cnt;\nreg [2:0] sum_i, sum_j;\n\n// Sum registers\nreg [63:0] sum_temp;\n\n// Edge decoding\nwire [3:0] A = edges[edge_idx][39:36];\nwire [3:0] B = edges[edge_idx][35:32];\nwire [31:0] L = edges[edge_idx][31:0];\n\n// State transition\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n    end else begin\n        state <= next_state;\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE:       if (start) next_state = INIT;\n        INIT:       if (init_i == 3'd7) next_state = LOAD_EDGES;\n        LOAD_EDGES: if (edge_idx == m_reg) next_state = FLOYD;\n        FLOYD:      if (k_cnt == n_reg) next_state = SUM;\n        SUM:        if (sum_i == n_reg-1) next_state = DONE_STATE;\n        DONE_STATE: next_state = IDLE;\n        default:    next_state = IDLE;\n    endcase\nend\n\n// Datapath\ninteger i, j;  // For loop indices\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        done <= 1'b0;\n        state <= IDLE;\n        n_reg <= 3'd0;\n        m_reg <= 4'd0;\n        edge_idx <= 4'd0;\n        init_i <= 3'd0;\n        init_j <= 3'd0;\n        k_cnt <= 3'd0;\n        i_cnt <= 3'd0;\n        j_cnt <= 3'd0;\n        sum_i <= 3'd0;\n        sum_j <= 3'd0;\n        sum_temp <= 64'd0;\n        \n        // Initialize danger array\n        for (i = 0; i < N_MAX; i = i + 1) begin\n            danger[i] <= 32'd0;\n        end\n        \n        // Initialize dist matrix\n        for (i = 0; i < N_MAX; i = i + 1) begin\n            for (j = 0; j < N_MAX; j = j + 1) begin\n                if (i == j) dist[i][j] <= 64'd0;\n                else dist[i][j] <= INF;\n            end\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    n_reg <= N;\n                    m_reg <= M;\n                    edge_idx <= 4'd0;\n                    init_i <= 3'd0;\n                    init_j <= 3'd0;\n                end\n            end\n            \n            INIT: begin\n                if (init_j == n_reg) begin\n                    init_j <= 3'd0;\n                    init_i <= init_i + 3'd1;\n                end else begin\n                    if (init_i == init_j) dist[init_i][init_j] <= 64'd0;\n                    else dist[init_i][init_j] <= INF;\n                    init_j <= init_j + 3'd1;\n                end\n            end\n            \n            LOAD_EDGES: begin\n                if (edge_idx < m_reg) begin\n                    if (A >= 4'd1 && A <= n_reg && B >= 4'd1 && B <= n_reg) begin\n                        dist[A-1][B-1] <= {32'd0, L};\n                        dist[B-1][A-1] <= {32'd0, L};\n                    end\n                    edge_idx <= edge_idx + 4'd1;\n                end\n            end\n            \n            FLOYD: begin\n                if (j_cnt < n_reg) begin\n                    if (i_cnt < n_reg) begin\n                        if (k_cnt < n_reg) begin\n                            if (dist[i_cnt][k_cnt] != INF && dist[k_cnt][j_cnt] != INF) begin\n                                if (dist[i_cnt][k_cnt] + dist[k_cnt][j_cnt] < dist[i_cnt][j_cnt]) begin\n                                    dist[i_cnt][j_cnt] <= dist[i_cnt][k_cnt] + dist[k_cnt][j_cnt];\n                                end\n                            end\n                            k_cnt <= k_cnt + 3'd1;\n                        end else begin\n                            k_cnt <= 3'd0;\n                            i_cnt <= i_cnt + 3'd1;\n                        end\n                    end else begin\n                        i_cnt <= 3'd0;\n                        j_cnt <= j_cnt + 3'd1;\n                    end\n                end else begin\n                    j_cnt <= 3'd0;\n                    k_cnt <= 3'd0;\n                end\n            end\n            \n            SUM: begin\n                if (sum_i < n_reg) begin\n                    if (sum_j == 3'd0) sum_temp <= 64'd0;\n                    if (sum_j < n_reg) begin\n                        sum_temp <= sum_temp + dist[sum_i][sum_j];\n                        sum_j <= sum_j + 3'd1;\n                    end else begin\n                        danger[sum_i] <= sum_temp % MOD;\n                        sum_i <= sum_i + 3'd1;\n                        sum_j <= 3'd0;\n                    end\n                end\n            end\n            \n            DONE_STATE: begin\n                done <= 1'b1;\n            end\n            \n            default: begin\n                state <= IDLE;\n            end\n        endcase\n    end\nend\n\nendmodule